import{_ as l,a0 as o,w as n,s as p,ao as r,I as d,x as i,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 上简单模拟系统负载的方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上简单模拟系统负载的方法 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上简单模拟系统负载的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上简单模拟系统负载的方法 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170924 Simulate System Loads","title":"在 Linux 上简单模拟系统负载的方法","tag":"201801","desc":""},"relativePath":"201801/20170924 Simulate System Loads.md","filePath":"[post].md"}'),h={name:"201801/20170924 Simulate System Loads.md"};function c(u,e,g,k,b,f){const s=o("Link");return n(),p("div",null,[e[13]||(e[13]=r(`<h1 id="在-linux-上简单模拟系统负载的方法" tabindex="-1">在 Linux 上简单模拟系统负载的方法 <a class="header-anchor" href="#在-linux-上简单模拟系统负载的方法" aria-label="Permalink to “在 Linux 上简单模拟系统负载的方法”">​</a></h1><p>系统管理员通常需要探索在不同负载对应用性能的影响。这意味着必须要重复地人为创造负载。当然，你可以通过专门的工具来实现，但有时你可能不想也无法安装新工具。</p><p>每个 Linux 发行版中都自带有创建负载的工具。他们不如专门的工具那么灵活，但它们是现成的，而且无需专门学习。</p><h3 id="cpu" tabindex="-1">CPU <a class="header-anchor" href="#cpu" aria-label="Permalink to “CPU”">​</a></h3><p>下面命令会创建 CPU 负荷，方法是通过压缩随机数据并将结果发送到 <code>/dev/null</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /dev/urandom | gzip -9 &gt; /dev/null</span></span></code></pre></div><p>如果你想要更大的负荷，或者系统有多个核，那么只需要对数据进行压缩和解压就行了，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /dev/urandom | gzip -9 | gzip -d | gzip -9 | gzip -d &gt; /dev/null</span></span></code></pre></div><p>按下 <code>CTRL+C</code> 来终止进程。</p><h3 id="内存占用" tabindex="-1">内存占用 <a class="header-anchor" href="#内存占用" aria-label="Permalink to “内存占用”">​</a></h3><p>下面命令会减少可用内存的总量。它是通过在内存中创建文件系统然后往里面写文件来实现的。你可以使用任意多的内存，只需哟往里面写入更多的文件就行了。</p><p>首先，创建一个挂载点，然后将 ramfs 文件系统挂载上去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir z</span></span>
<span class="line"><span>mount -t ramfs ramfs z/</span></span></code></pre></div><p>第二步，使用 <code>dd</code> 在该目录下创建文件。这里我们创建了一个 128M 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dd if=/dev/zero of=z/file bs=1M count=128</span></span></code></pre></div><p>文件的大小可以通过下面这些操作符来修改：</p><ul><li><code>bs=</code> 块大小。可以是任何数字后面接上 <code>B</code>（表示字节），<code>K</code>（表示 KB），<code>M</code>（ 表示 MB）或者 <code>G</code>（表示 GB）。</li><li><code>count=</code> 要写多少个块。</li></ul><h3 id="磁盘-i-o" tabindex="-1">磁盘 I/O <a class="header-anchor" href="#磁盘-i-o" aria-label="Permalink to “磁盘 I/O”">​</a></h3><p>创建磁盘 I/O 的方法是先创建一个文件，然后使用 <code>for</code> 循环来不停地拷贝它。</p><p>下面使用命令 <code>dd</code> 创建了一个全是零的 1G 大小的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dd if=/dev/zero of=loadfile bs=1M count=1024</span></span></code></pre></div><p>下面命令用 <code>for</code> 循环执行 10 次操作。每次都会拷贝 <code>loadfile</code> 来覆盖 <code>loadfile1</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in {1..10}; do cp loadfile loadfile1; done</span></span></code></pre></div><p>通过修改 <code>{1..10}</code> 中的第二个参数来调整运行时间的长短。（LCTT 译注：你的 Linux 系统中的默认使用的 <code>cp</code> 命令很可能是 <code>cp -i</code> 的别名，这种情况下覆写会提示你输入 <code>y</code> 来确认，你可以使用 <code>-f</code> 参数的 <code>cp</code> 命令来覆盖此行为，或者直接用 <code>/bin/cp</code> 命令。）</p><p>若你想要一直运行，直到按下 <code>CTRL+C</code> 来停止，则运行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>while true; do cp loadfile loadfile1; done</span></span></code></pre></div><hr>`,27)),d("p",null,[e[1]||(e[1]=i("via: ",-1)),a(s,{href:"https://bash-prompt.net/guides/create-system-load/"},{default:t(()=>[...e[0]||(e[0]=[i("https://bash-prompt.net/guides/create-system-load/",-1)])]),_:1})]),d("p",null,[e[5]||(e[5]=i("作者：",-1)),a(s,{href:"https://bash-prompt.net"},{default:t(()=>[...e[2]||(e[2]=[i("Elliot Cooper",-1)])]),_:1}),e[6]||(e[6]=i(" 译者：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[i("lujun9972",-1)])]),_:1}),e[7]||(e[7]=i(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),d("p",null,[e[10]||(e[10]=i("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原创编译，",-1)),a(s,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[i("Linux中国",-1)])]),_:1}),e[12]||(e[12]=i(" 荣誉推出",-1))])])}const y=l(h,[["render",c]]);export{x as __pageData,y as default};
